sys_script_client.script:
function onSubmit() {
    //Type appropriate comment here, and begin script below
    //MSSTRUSTES-175, MSSTRUSTES-173
    var hkIdVisible = g_form.isVisible('identification_hkid_card_auth_pers_1');
    var passportVisible = g_form.isVisible('identification_passportno_auth_pers_1');


    // Only validate if both fields are visible
    if (hkIdVisible && passportVisible) {
        var hkId = g_form.getValue('identification_hkid_card_auth_pers_1');
        var passport = g_form.getValue('identification_passportno_auth_pers_1');
        if (!hkId && !passport) {
            g_form.showFieldMsg('identification_hkid_card_auth_pers_1', 'Either HK ID or Passport Number must be filled.', 'error');
            g_form.showFieldMsg('identification_passportno_auth_pers_1', 'Either HK ID or Passport Number must be filled.', 'error');
            return false;
        }

		if(passport) return true;
		var len = hkId.length;
		if (len < 2 || hkId.charAt(len - 1) !== ')' || hkId.charAt(len-3) !=='(' ) {
			g_form.showFieldMsg('identification_hkid_card_auth_pers_1', 'A bracket () between HKID and Check Digit is required in this field.', 'error');
			return false; // Prevent form submission
		}
		return true;
    }
    return true;

}
